  'apps.title': 'Apps voor gemeenschapscoördinatie',
  'apps.subtitle': 'Een suite van apps ontworpen voor het delen van informatie en coördinatie. Elk slaat gegevens op in leesbare formaten die synchroniseren tussen apparaten via elk beschikbaar transport.',
  'apps.chat.title': 'Chat',
  'apps.chat.desc': 'Realtime berichten met kamer-gebaseerde kanalen en directe berichten. Ondersteunt bestandsbijlagen, spraakberichten, locatiedeling en peilingen. Werkt met alle verbindingstypen.',
  'apps.blog.title': 'Blog',
  'apps.blog.desc': 'Lange-vorm publiceren met markdown-content, concepten, tags en reacties. Maak lokale journalistiek en gemeenschapsnieuwsbrieven die volledig offline werken.',
  'apps.work.title': 'Werk',
  'apps.work.desc': 'Offline Google Docs-alternatief. Spreadsheets, documenten, presentaties en formulieren met realtime samenwerking wanneer verbonden.',
  'apps.events.title': 'Evenementen',
  'apps.events.desc': 'Gemeenschapskalenders met evenementdetails, locaties, mediagalerijen en deelnemerstracking. Perfect voor het organiseren van bijeenkomsten en hulpverdelingen.',
  'apps.places.title': 'Plaatsen',
  'apps.places.desc': 'Geografische punten van belang met beschrijvingen en foto\'s. Documenteer waterbronnen, schuilplaatsen, voorraaddepots of gevaren zonder commerciële kaartdiensten.',
  'apps.alerts.title': 'Waarschuwingen',
